public enum VimivoFfiError {

    
    
    case DatabaseError(reason: String
    )
    case NotFound(reason: String
    )
    case InternalError(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeVimivoFfiError: FfiConverterRustBuffer {
    typealias SwiftType = VimivoFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> VimivoFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .DatabaseError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotFound(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InternalError(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: VimivoFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .DatabaseError(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .NotFound(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InternalError(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


